/*
 * A120239  Split-floor-multiplier sequence (SFMS) using multipliers 1/tau and
 *          tau, where tau=(1+sqrt(5))/2. (SFMS is defined at A120229.).
 * https://oeis.org/A120239
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = floor(n/φ) if floor(n/φ) > 0 and not already used,
 *            otherwise floor(n·φ) where φ = (1+√5)/2. This implements the
 *            split‑floor‑multiplier sequence (SFMS) of A120239, using the
 *            Beatty sequences generated by φ and its reciprocal
 * Range:     u8 n <= 70, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* Integer square‑root of a 128‑bit unsigned integer.
   Returns floor(sqrt(v)). */
static seq_t isqrt_u128(unsigned __int128 v)
{
    unsigned __int128 result = 0;
    unsigned __int128 bit = (unsigned __int128)1 << 126;   /* largest power of four ≤ 2^128-1 */

    while (bit > v)
        bit >>= 2;                 /* move to largest fitting power of four */

    while (bit != 0) {
        if (v >= result + bit) {
            v -= result + bit;
            result = (result >> 1) + bit;
        } else {
            result >>= 1;
        }
        bit >>= 2;
    }
    return (seq_t)result;          /* cast to seq_t is safe for the ranges we use */
}

/* Ensure that the 'used' bitmap can hold indices up to 'idx'. */
static void ensure_used_cap(size_t idx, bool **used, size_t *cap)
{
    if (idx < *cap)
        return;
    size_t new_cap = (*cap) ? (*cap << 1) : 64;
    while (idx >= new_cap)
        new_cap <<= 1;
    bool *tmp = (bool *)realloc(*used, new_cap * sizeof(bool));
    if (!tmp) abort();            /* allocation failure */
    for (size_t i = *cap; i < new_cap; ++i)
        tmp[i] = false;
    *used = tmp;
    *cap = new_cap;
}

/* Ensure that the sequence array can hold 'len' elements. */
static void ensure_seq_cap(idx_t len, seq_t **seq, size_t *cap)
{
    if ((size_t)len <= *cap)
        return;
    size_t new_cap = (*cap) ? (*cap << 1) : 16;
    while ((size_t)len > new_cap)
        new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(*seq, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    *seq = tmp;
    *cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined for n < 1, but return 0 */

    /* static state */
    static seq_t *seq = NULL;
    static size_t seq_cap = 0;
    static idx_t seq_len = 0;

    static bool *used = NULL;
    static size_t used_cap = 0;

    /* generate values up to 'n' if necessary */
    while (seq_len < n) {
        idx_t cur = seq_len + 1;            /* 1‑based index */
        seq_t idx_seq = (seq_t)cur;

        /* compute floor(cur * φ) = (cur + floor(cur * √5)) / 2 */
        unsigned __int128 sq = (unsigned __int128)5 * (unsigned __int128)idx_seq * (unsigned __int128)idx_seq;
        seq_t sqrt5 = isqrt_u128(sq);
        seq_t phi_floor = (idx_seq + sqrt5) / 2;

        /* compute floor(cur / φ) = φ_floor - cur (since 1/φ = φ - 1) */
        seq_t r_floor = phi_floor - idx_seq;

        seq_t chosen;
        if (r_floor > 0) {
            ensure_used_cap((size_t)r_floor, &used, &used_cap);
            if (!used[(size_t)r_floor]) {
                chosen = r_floor;
            } else {
                chosen = phi_floor;
            }
        } else {
            chosen = phi_floor;
        }

        /* mark chosen as used and store */
        ensure_used_cap((size_t)chosen, &used, &used_cap);
        used[(size_t)chosen] = true;

        ensure_seq_cap(seq_len + 1, &seq, &seq_cap);
        seq[seq_len] = chosen;
        ++seq_len;
    }

    return seq[n - 1]; /* seq is 0‑based, n is 1‑based */
}
